-- Project Sealed Hold Phase 3: immutable repair plans and recovery evidence.
CREATE TABLE `PrivateRepairPlan` (`id` VARCHAR(191) NOT NULL, `digest` CHAR(64) NOT NULL, `snapshotDigest` CHAR(64) NOT NULL, `state` VARCHAR(64) NOT NULL DEFAULT 'DRAFT', `dryRun` BOOLEAN NOT NULL DEFAULT true, `expiresAt` DATETIME(3) NOT NULL, `approvedById` VARCHAR(191) NULL, `approvedAt` DATETIME(3) NULL, `executionLease` VARCHAR(191) NULL, `executionUntil` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `PrivateRepairPlan_digest_key` (`digest`), KEY `PrivateRepairPlan_state_expiresAt_idx` (`state`,`expiresAt`));
CREATE TABLE `PrivateRepairAction` (`id` VARCHAR(191) NOT NULL, `planId` VARCHAR(191) NOT NULL, `ordinal` INTEGER NOT NULL, `action` VARCHAR(64) NOT NULL, `opaqueTarget` VARCHAR(191) NOT NULL, `preconditionDigest` CHAR(64) NOT NULL, `state` VARCHAR(64) NOT NULL DEFAULT 'PENDING', `resultCode` VARCHAR(191) NULL, PRIMARY KEY (`id`), UNIQUE KEY `PrivateRepairAction_planId_ordinal_key` (`planId`,`ordinal`), CONSTRAINT `PrivateRepairAction_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `PrivateRepairPlan`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `PrivateBackupRun` (`id` VARCHAR(191) NOT NULL, `backupId` VARCHAR(191) NOT NULL, `state` VARCHAR(64) NOT NULL, `manifestDigest` CHAR(64) NOT NULL, `snapshotIdentity` VARCHAR(191) NOT NULL, `objectSetDigest` CHAR(64) NOT NULL, `keyVersions` LONGTEXT NOT NULL, `verifiedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `PrivateBackupRun_backupId_key` (`backupId`), KEY `PrivateBackupRun_state_createdAt_idx` (`state`,`createdAt`));
CREATE TABLE `PrivateRestoreDrill` (`id` VARCHAR(191) NOT NULL, `backupRunId` VARCHAR(191) NOT NULL, `targetIdentity` VARCHAR(191) NOT NULL, `state` VARCHAR(64) NOT NULL, `resultCode` VARCHAR(191) NULL, `cleanupCompletedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `PrivateRestoreDrill_backupRunId_createdAt_idx` (`backupRunId`,`createdAt`));
CREATE TABLE `PrivateKeyLifecycleRecord` (`id` VARCHAR(191) NOT NULL, `provider` VARCHAR(191) NOT NULL, `sourceVersion` VARCHAR(191) NULL, `destinationVersion` VARCHAR(191) NOT NULL, `state` VARCHAR(64) NOT NULL, `plannedCount` INTEGER NOT NULL DEFAULT 0, `completedCount` INTEGER NOT NULL DEFAULT 0, `retirementApprovedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `PrivateKeyLifecycle_provider_destination_created_idx` (`provider`,`destinationVersion`,`createdAt`));
